'use strict';
// ═══════════════════════════════════════════════════════════════
// Omni Code — 多國語言（i18n）
// ═══════════════════════════════════════════════════════════════
// 五種介面語系：en（預設）/ zh-TW / zh-CN / ja / ko。
// 持久化：OC.cfg.locale → data/config.json（後端白名單見 settings.php）；
// 本地鏡像 localStorage oc_locale（開機第一幀就用它，避免閃爍）。
//
// 用法：t('settings.title')、t('usage.cards.calls')；{name} 插值。
// 找不到鍵 → 回退 en → 再找不到回傳鍵本身（絕不炸面板）。
// 靜態 chrome（rail、dock、對話框標頭…）由 applyChromeI18n() 按 ID 重寫，
// 各面板的動態內容在各自 render 時直接呼叫 t()。
// ═══════════════════════════════════════════════════════════════

