// ─── 取值 ─────────────────────────────────────────────────────────
function oc_locale() {
    const l = (window.OC?.cfg?.locale) || (() => { try { return localStorage.getItem('oc_locale'); } catch { return ''; } })() || 'en';
    return OC_I18N[l] ? l : 'en';
}

/** 翻譯：t('settings.title')、t('usage.more', {n: 5}) */
function t(key, vars) {
    const loc = oc_locale();
    let s = OC_I18N[loc]?.[key];
    if (s === undefined) s = OC_I18N['en']?.[key];
    if (s === undefined) return key;
    if (vars) for (const [k, v] of Object.entries(vars)) s = s.split('{' + k + '}').join(String(v ?? ''));
    return s;
}

/** 依語系的 <html lang> 對照 */
function oc_html_lang(loc) { return OC_HTML_LANG[loc] || 'en'; }

/** 是否為「工作區已切換」提示（五語系皆認，用於靜音切換時的過濾） */
function isWsSwitchedMsg(msg) {
    const s = String(msg || '');
    for (const l of Object.keys(OC_I18N)) {
        const tpl = OC_I18N[l]?.['ws.switched'] || '';
        const prefix = tpl.split('{ws}')[0];
        if (prefix && s.startsWith(prefix)) return true;
    }
    return false;
}

/** 日期顯示用的 locale（跟著介面語系走；toLocaleDateString 寫死語系會讓英文版冒出中文日期） */
function oc_date_locale() {
    return { en: 'en-US', 'zh-TW': 'zh-TW', 'zh-CN': 'zh-CN', ja: 'ja-JP', ko: 'ko-KR' }[oc_locale()] || 'en-US';
}

// ─── 切換語系 ─────────────────────────────────────────────────────
// 新偏好即時存檔（config.json + localStorage 雙寫；存檔失敗不擋 UI）。
async function setLocale(loc, { save = true, rerender = true } = {}) {
    if (!OC_I18N[loc]) return false;
    if (window.OC?.cfg) OC.cfg.locale = loc;
    try { localStorage.setItem('oc_locale', loc); } catch {}
    try { document.documentElement.lang = oc_html_lang(loc); } catch {}
    if (save && window.SETTINGS?.set) {
        SETTINGS.set({ locale: loc }).catch(e => console.warn('[i18n] locale 存檔失敗', e.message));
    }
    if (rerender) {
        try { applyChromeI18n(); } catch (e) { console.warn('[i18n] chrome 套用失敗', e.message); }
        try { window.renderPermButton?.(); } catch {}
        try { window.renderEffortButton?.(); } catch {}
        try { window.paintModeChrome?.(); } catch {}
        // 目前開著的面板即時重畫
        try {
            const p = window.OC?.panel;
            if (p === 'settings') window.renderSettingsPanel?.();
            else if (p === 'models') window.renderModelsPanel?.();
            else if (p === 'usage') window.loadUsage?.(true);
            else if (p === 'sessions') window.renderSessionsPanel?.(true);
            else if (p === 'memory') window.renderMemoryPanel?.();
            else if (p === 'skills') window.renderSkillsPanel?.(true);
            else if (p === 'mcp') window.renderMcpPanel?.(true);
        } catch {}
        // 語系切換不中斷對話：已渲染的訊息保留，新訊息才用新語系
    }
    return true;
}

// ─── 靜態 chrome 套用 ─────────────────────────────────────────────
// index.html 的靜態文字全部在這裡按 ID 重寫 —— HTML 本體只留英文，
// 切換語系時不必動 index.html。
function applyChromeI18n() {
    const Q = (s, r) => (r || document).querySelector(s);
    const QA = (s, r) => Array.from((r || document).querySelectorAll(s));

    try { document.documentElement.lang = oc_html_lang(oc_locale()); } catch {}
    const sp = Q('#splash .splash-sub'); if (sp) sp.textContent = t('splash.sub');

    // 頂列
    const ws = $('ws-picker'); if (ws) ws.title = t('top.wsTitle');
    const mcb = $('mode-chat-btn');
    if (mcb) { mcb.title = t('top.chatTitle'); const s = mcb.querySelectorAll('span')[1]; if (s) s.textContent = t('top.chat'); }
    const mb = $('model-btn'); if (mb) mb.title = t('top.modelTitle');
    const eb = $('effort-btn'); if (eb) eb.title = t('top.effortTitle');
    const mdb = $('mode-btn'); if (mdb) mdb.title = t('top.modeTitle');
    const kb = $('keys-btn'); if (kb) kb.title = t('top.keysTitle');
    const tb = $('theme-btn'); if (tb) tb.title = t('top.themeTitle');
    const lb = $('layout-swap-btn'); if (lb) lb.title = t('top.layoutTitle');
    const cb = $('chat-toggle-btn'); if (cb) cb.title = t('top.chatToggleTitle');

    // 左側圖示列
    const railMap = {
        files: 'rail.files', search: 'rail.search', sessions: 'rail.sessions',
        memory: 'rail.memory', skills: 'rail.skills', mcp: 'rail.mcp',
        models: 'rail.models', usage: 'rail.usage', settings: 'rail.settings',
    };
    for (const b of QA('.rail-btn[data-panel]')) {
        const k = railMap[b.dataset.panel];
        if (k) b.dataset.tip = t(k);
    }
    const ib = $('image-btn'); if (ib) ib.dataset.tip = t('rail.image');

    // 靜態面板標頭（模型／流量／設定由 JS 渲染，這裡只處理靜態那幾個）
    const headMap = {
        'panel-files': 'panel.files', 'panel-search': 'panel.search',
        'panel-sessions': 'panel.sessions', 'panel-memory': 'panel.memory',
        'panel-skills': 'panel.skills', 'panel-mcp': 'panel.mcp',
        'panel-settings': 'panel.settings',
    };
    for (const [id, k] of Object.entries(headMap)) {
        const h = Q('#' + id + ' .panel-title'); if (h) h.textContent = t(k);
    }
    const ft = { 'ft-new-file': 'files.newFile', 'ft-new-dir': 'files.newDir', 'ft-collapse': 'files.collapse', 'ft-refresh': 'files.refresh' };
    for (const [id, k] of Object.entries(ft)) { const b = $(id); if (b) b.title = t(k); }
    const sn = $('sess-new'); if (sn) sn.title = t('chat.new');
    const mn = $('mem-new'); if (mn) mn.title = t('common.add');
    const mr = $('mem-refresh'); if (mr) mr.title = t('common.refresh');
    const skn = $('skill-new'); if (skn) skn.title = t('common.add');
    const skr = $('skill-refresh'); if (skr) skr.title = t('common.refresh');
    const mcn = $('mcp-add'); if (mcn) mcn.title = t('common.add');
    const mcr = $('mcp-refresh'); if (mcr) mcr.title = t('common.refresh');

    // 下方面板
    const dockMap = { terminal: 'dock.terminal', diff: 'dock.diff', problems: 'dock.problems', preview: 'dock.preview' };
    for (const d of QA('.dock-tab[data-dock]')) {
        const k = dockMap[d.dataset.dock]; if (!k) continue;
        const ico = d.querySelector('.ms');
        d.innerHTML = '';
        d.appendChild(el('span', { class: 'ms', text: ico ? ico.textContent : 'terminal' }));
        d.appendChild(document.createTextNode(' ' + t(k)));
    }
    const pe = Q('#dock-problems .dock-empty');
    if (pe) pe.innerHTML = esc(t('dock.problemsEmpty')) + '<br><span class="dim">' + esc(t('dock.problemsHint')) + '</span>';
    const pu = $('preview-url'); if (pu) pu.placeholder = t('dock.previewPh');
    const pg = $('preview-go'); if (pg) pg.textContent = t('common.go');
    const pr = $('preview-reload'); if (pr) pr.title = t('dock.reload');
    const px = $('preview-ext'); if (px) px.title = t('dock.openExt');
    const dt = $('dock-toggle'); if (dt) dt.title = t('dock.toggle');
    const rd = $('resizer-dock'); if (rd) rd.title = t('dock.resize');

    // 對話欄（模式相關的 placeholder／hint 交給 paintModeChrome）
    const cs = $('chat-self'); if (cs) cs.title = t('chat.self');
    const cn = $('chat-new'); if (cn) cn.title = t('chat.new');
    const ch = $('chat-history'); if (ch) ch.title = t('chat.history');
    const cc = $('chat-compact'); if (cc) cc.title = t('chat.compact');
    const ca = $('chat-attach'); if (ca) ca.title = t('chat.attach');
    const cx = $('chat-extra'); if (cx) cx.title = t('ws.extraT');
    const csd = $('chat-send'); if (csd) csd.title = t('chat.send');
    const cst = $('chat-stop'); if (cst) cst.title = t('chat.stop');
    try { window.paintModeChrome?.(); } catch {}

    // 編輯器空白頁
    const ees = Q('#editor-empty .ee-sub'); if (ees) ees.textContent = t('editor.emptySub');
    const eek = QA('#editor-empty .ee-keys span:last-child');
    const eekT = ['editor.kQuick', 'editor.kSearch', 'editor.kTerm', 'editor.kSave', 'editor.kMode', 'editor.kSend'];
    eek.forEach((s, i) => { if (eekT[i]) s.textContent = t(eekT[i]); });

    // Modal 靜態標頭
    const kh = Q('#modal-keys .modal-head span'); if (kh) kh.textContent = t('keys.title');
    const wh = Q('#modal-workspace .modal-head span'); if (wh) wh.textContent = t('ws.title');
    const xh = $('modal-extra-title'); if (xh) xh.textContent = t('ws.extraT');
    const eh = Q('#modal-entry .modal-head span');
    if (eh) eh.innerHTML = '<span class="ms">waving_hand</span>' + esc(t('entry.title'));
    const ph = $('modal-permission-title');
    if (ph && !ph.dataset.dirty) ph.textContent = t('perm.title');
}

/** 開機第一幀就決定的語系（config 還沒回來前先用 localStorage 頂著；預設英文） */
function initLocaleEarly() {
    let l = '';
    try { l = localStorage.getItem('oc_locale') || ''; } catch {}
    if (!OC_I18N[l]) l = 'en';
    try { document.documentElement.lang = oc_html_lang(l); } catch {}
    return l;
}

Object.assign(window, {
    OC_LOCALES, OC_I18N, OC_HTML_LANG, t, oc_locale, oc_html_lang, oc_date_locale, setLocale, applyChromeI18n, initLocaleEarly,
    isWsSwitchedMsg,
});
